#define ALL(v) v.begin(),v.end()
#define sz(a) a.size();
#define endl '\n'
#define MAX 10010

typedef long long i64;
typedef pair<int,int> pii;

//const int MOD = ;

string solve,s; int N;

void Check(){

	if(solve[0] == '.'){
		solve.remove(0,1);
		solve = "dot" + solve;
	}
	else if(solve[0] == '@'){
		solve.remove(0,1);
		solve = "at" + solve;
	}

	if(solve[solve.size() - 1] == '.'){
		solve.remove(solve.size() - 1,1);
		solve += "dot";
	}
	else if(solve[solve.size() - 1] == '@'){
		solve.remove(solve.size() - 1,1);
		solve += "at";
	}

}

int main()
{
	ios_base :: sync_with_stdio(0);
	cin.tie(0);

	cin >> s;

	N = sz(s);

	solve = "";

	for(int I = 0;I < N;++I){

		if(I + 3 <= N){
			if(s.substr(I,3) == "dot"){
				solve += ".";
				I+=2;
			}
			else{
				if(I + 2 <= N){
					if(s.substr(I,2) == "at"){
						solve += "@";
						I+=1;
					}
					else solve += s[I];
				}
				else solve += s[I];
			}
		}
		else if(I + 2 <= N){
			if(s.substr(I,2) == "at"){
				solve += "@";
				I+=1;
			}
			else solve += s[I];
		}
		else solve += s[I];
	}

	Check();

	int cont = 0;

	for(int I = 0;I < solve.size();++I){

		if(solve[I] == '@') ++cont;

	}

	if(cont == 1) cout << solve << endl;

	else{

		bool ok = 1;

		for(int I = 0;I < solve.size();++I){

			if(solve[I] == '@'){
				if(ok){
					cout << '@';
					ok = false;
				}
				else{
					cout << "at";
				}
				continue;
			}
			cout << solve[I];
		}
		cout << endl;
	}
}
